import{_ as r,C as o,o as s,c as i,j as a,a as l,E as t,a6 as c}from"./chunks/framework.CD0vXS2f.js";const h=JSON.parse('{"title":"02 · Global vs. Data Zone vs. Regional Residency Matrix","description":"Mapping regulatory sovereignty contracts to Microsoft Foundry deployment types (Global, Data Zone, Regional Provisioned & Standard) across primary and failover stamps.","frontmatter":{"title":"02 · Global vs. Data Zone vs. Regional Residency Matrix","description":"Mapping regulatory sovereignty contracts to Microsoft Foundry deployment types (Global, Data Zone, Regional Provisioned & Standard) across primary and failover stamps."},"headers":[],"relativePath":"playbooks/multi-region-bcp/02-residency-and-sku-matrix.md","filePath":"playbooks/multi-region-bcp/02-residency-and-sku-matrix.md","lastUpdated":1795280666087}'),g={name:"playbooks/multi-region-bcp/02-residency-and-sku-matrix.md"};function y(p,e,m,f,v,u){const n=o("PlaybookMeta"),d=o("PageBrief");return s(),i("div",null,[e[0]||(e[0]=a("h1",{id:"_02-·-global-vs-data-zone-vs-regional-residency-matrix",tabindex:"-1"},[l("02 · Global vs. Data Zone vs. Regional Residency Matrix "),a("a",{class:"header-anchor",href:"#_02-·-global-vs-data-zone-vs-regional-residency-matrix","aria-label":'Permalink to "02 · Global vs. Data Zone vs. Regional Residency Matrix"'},"​")],-1)),t(n,{track:"03 · Multi-Region Foundry BCP, Residency & Failover Drills",verified:"2026-11-19 PST",status:"Live v2.0",studioHref:"/studio/#bcp",studioLabel:"BCP Residency Advisor →"}),t(d,{stage:"qualify",readTime:"4 min read",problem:"Mixing Global spillover endpoints behind a Regional or Data Zone primary PTU-M deployment silently violates data-processing residency clauses the moment a 429 burst occurs.",takeaway:"Enforce Residency Symmetry across Primary, Local Spillover, and Secondary DR backends: every backend in an APIM pool must belong to the same or stricter residency tier.",csaUse:"Walk Risk/Legal and Cloud Security through the deployment matrix below to lock in the allowed SKU family before requesting quota."}),e[1]||(e[1]=c('<h2 id="_1-microsoft-foundry-deployment-scope-boundaries-m" tabindex="-1">1. Microsoft Foundry Deployment Scope Boundaries <code>[M]</code> <a class="header-anchor" href="#_1-microsoft-foundry-deployment-scope-boundaries-m" aria-label="Permalink to &quot;1. Microsoft Foundry Deployment Scope Boundaries `[M]`&quot;">​</a></h2><p>Microsoft Foundry offers three geographic processing scopes across both <strong>Provisioned (<code>PTU-M</code>)</strong> and <strong>Standard (<code>PAYG</code>)</strong> SKUs <span class="ev-badge ev-m">[M]</span>:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Deployment Scope</th><th style="text-align:left;">Data-at-Rest Location</th><th style="text-align:left;">Inference Compute &amp; Prompt KV Cache Location</th><th style="text-align:left;">Min PTU (<code>gpt-6.1-sol</code>)</th><th style="text-align:left;">Best Fit</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Global</strong> (<code>GlobalProvisionedManaged</code> / <code>GlobalStandard</code>)</td><td style="text-align:left;">Resource&#39;s Azure geography <span class="ev-badge ev-m">[M]</span></td><td style="text-align:left;">May process in any global Azure AI location; KV cache isolated to subscription <span class="ev-badge ev-m">[M]</span>.</td><td style="text-align:left;"><code>15 PTU</code> (inc <code>5</code>) <span class="ev-badge ev-m">[M]</span></td><td style="text-align:left;">Non-sovereign enterprise workloads prioritizing highest TPM ceiling and fastest model availability.</td></tr><tr><td style="text-align:left;"><strong>Data Zone</strong> (<code>DataZoneProvisionedManaged</code> / <code>DataZoneStandard</code>)</td><td style="text-align:left;">Resource&#39;s Azure geography <span class="ev-badge ev-m">[M]</span></td><td style="text-align:left;">Strictly confined within <strong>Microsoft-defined Data Zone (<code>US</code> or <code>EU</code>)</strong> across both compute and temporary KV cache <span class="ev-badge ev-m">[M]</span>.</td><td style="text-align:left;"><code>15 PTU</code> (inc <code>5</code>) <span class="ev-badge ev-m">[M]</span></td><td style="text-align:left;"><strong>Recommended regulated default</strong> for US federal/financial/tax/advisory or EU GDPR workloads allowing intra-US or intra-EU failover.</td></tr><tr><td style="text-align:left;"><strong>Regional</strong> (<code>ProvisionedManaged</code> / <code>Standard</code>)</td><td style="text-align:left;">Single target Azure region <span class="ev-badge ev-m">[M]</span></td><td style="text-align:left;">Strictly confined to the <strong>single deployed Azure region</strong> <span class="ev-badge ev-m">[M]</span>.</td><td style="text-align:left;"><code>25 PTU</code> (<code>15</code> on <code>5.6</code> / <code>6-sol</code>) <span class="ev-badge ev-m">[M]</span></td><td style="text-align:left;">Single-country sovereignty mandates outside US/EU Data Zones (e.g., UK, Canada, Australia, Switzerland, Japan) or sub-10ms intra-region co-location.</td></tr></tbody></table><hr><h2 id="_2-the-golden-rule-of-residency-symmetry-arch" tabindex="-1">2. The Golden Rule of Residency Symmetry <code>[Arch]</code> <a class="header-anchor" href="#_2-the-golden-rule-of-residency-symmetry-arch" aria-label="Permalink to &quot;2. The Golden Rule of Residency Symmetry `[Arch]`&quot;">​</a></h2><div class="danger custom-block"><p class="custom-block-title">Never Spill Down-Boundary (<code>Data Zone</code> → <code>Global</code> or <code>Regional</code> → <code>Global</code>)</p><p>An APIM failover policy only triggers during peak filing cliffs or regional incidents—meaning normal weekday compliance scans see <code>100%</code> in-region traffic while peak client bursts silently route to <code>GlobalStandard</code> if misconfigured.</p></div><p>Enforce <strong>Residency Symmetry</strong> in Bicep and Azure Policy (<code>Microsoft.CognitiveServices/accounts/deployments</code>):</p><ol><li><strong>Data Zone US Stamp:</strong> Primary <code>DataZoneProvisionedManaged</code> (East US 2) → Local Spillover <code>DataZoneStandard</code> (East US 2) → Secondary DR <code>DataZoneStandard</code> / <code>DataZoneProvisionedManaged</code> (Central US or West US 3).</li><li><strong>Data Zone EU Stamp:</strong> Primary <code>DataZoneProvisionedManaged</code> (Sweden Central) → Local Spillover <code>DataZoneStandard</code> (Sweden Central) → Secondary DR <code>DataZoneStandard</code> / <code>DataZoneProvisionedManaged</code> (Germany West Central or France Central).</li><li><strong>Single-Jurisdiction Regional Stamp (e.g., UK / Canada):</strong> Primary <code>ProvisionedManaged</code> (UK South) → Secondary DR <code>Standard</code> / <code>ProvisionedManaged</code> (UK West)—verifying <strong>exact model + snapshot availability</strong> in both regions before cutover <span class="ev-badge ev-validate">[Validate]</span>.</li></ol>',8))])}const S=r(g,[["render",y]]);export{h as __pageData,S as default};
